export type StatusEvent = {
  runId: string;
  step: string;
  status: 'started' | 'done' | 'failed';
  at: string;
  costUsd?: number;
};

export function renderStatus(events: StatusEvent[], budgetUsd: number): string {
  if (events.length === 0) return 'no runs yet';

  const byTime = events
    .map((e, i) => ({ e, i }))
    .sort((a, b) => Date.parse(a.e.at) - Date.parse(b.e.at) || a.i - b.i)
    .map((x) => x.e);
  const runId = byTime[byTime.length - 1].runId;
  const run = byTime.filter((e) => e.runId === runId);

  const latest = new Map<string, StatusEvent['status']>();
  for (const e of run) latest.set(e.step, e.status);

  const lastDone = [...run].reverse().find((e) => e.status === 'done');
  const inProgress = [...latest].filter(([, s]) => s === 'started').map(([k]) => k);
  const failed = [...latest].filter(([, s]) => s === 'failed').map(([k]) => k);
  const cost = run.reduce((sum, e) => sum + (e.costUsd ?? 0), 0);

  const lines = [`run ${runId}`, `last completed step: ${lastDone ? lastDone.step : 'none'}`];
